use anyhow::Result;
use small_http::{Request, Response, Status};

use crate::context::Context;
use crate::controllers::require_auth;
use crate::imports::google_keep;

// MARK: Handlers
pub(crate) fn imports_google_keep(req: &Request, ctx: &Context) -> Result<Response> {
    let user = require_auth!(ctx);

    let zip_bytes = match req.body.as_deref() {
        Some(b) if !b.is_empty() => b,
        _ => return Ok(Response::with_status(Status::BadRequest)),
    };

    let count = google_keep::import_from_zip_bytes(zip_bytes, ctx, user.id)?;

    Ok(Response::with_json(crate::api::ImportGoogleKeepResponse {
        count: count as i64,
    }))
}

