    fn post_import(
        router: &small_router::Router<crate::context::Context>,
        token: &str,
        zip: &[u8],
    ) -> Response {
        router.handle(
            Request::post("http://localhost/api/imports/google-keep")
                .header("Authorization", format!("Bearer {token}"))
                .header("Content-Type", "application/zip")
                .body(zip.to_vec()),
        )
    }

    #[test]
    fn test_imports_google_keep() {
        let ctx = Context::with_test_database().expect("Can't create test database");
        let router = router(ctx.clone());
        let (_, token) = create_test_user_with_session(&ctx);

        let res = post_import(&router, &token, TWO_NOTES_ZIP);
        assert_eq!(res.status, Status::Ok);
        let resp = serde_json::from_slice::<api::ImportGoogleKeepResponse>(&res.body).unwrap();
        assert_eq!(resp.count, 2);
    }

    #[test]
    fn test_imports_google_keep_empty_notes_skipped() {
        let ctx = Context::with_test_database().expect("Can't create test database");
        let router = router(ctx.clone());
        let (_, token) = create_test_user_with_session(&ctx);

        let res = post_import(&router, &token, EMPTY_AND_VALID_ZIP);
        assert_eq!(res.status, Status::Ok);
        let resp = serde_json::from_slice::<api::ImportGoogleKeepResponse>(&res.body).unwrap();
        assert_eq!(resp.count, 1);
    }

    #[test]
    fn test_imports_google_keep_rolls_back_database_error() {
        let ctx = Context::with_test_database().expect("Can't create test database");
        let router = router(ctx.clone());
        let (_, token) = create_test_user_with_session(&ctx);
        ctx.database
            .execute_script(
                "CREATE TRIGGER reject_second_note BEFORE INSERT ON notes
                WHEN NEW.title = 'Second'
                BEGIN
                    SELECT RAISE(FAIL, 'rejected note');
                END;",
            )
            .unwrap();

        let res = post_import(&router, &token, TWO_NOTES_ZIP);

        assert_eq!(res.status, Status::InternalServerError);
        let count = ctx
            .database
            .query_some::<i64>("SELECT COUNT(*) FROM notes", ())
            .unwrap();
        assert_eq!(count, 0);
    }

    #[test]
    fn test_imports_google_keep_empty_body() {
        let ctx = Context::with_test_database().expect("Can't create test database");
        let router = router(ctx.clone());
        let (_, token) = create_test_user_with_session(&ctx);

        let res = router.handle(
            Request::post("http://localhost/api/imports/google-keep")
                .header("Authorization", format!("Bearer {token}"))
                .header("Content-Type", "application/zip"),
        );
        assert_eq!(res.status, Status::BadRequest);
    }

    #[test]
    fn test_imports_google_keep_unauthorized() {
        let ctx = Context::with_test_database().expect("Can't create test database");
        let router = router(ctx.clone());

        let res = router.handle(
            Request::post("http://localhost/api/imports/google-keep")
                .header("Content-Type", "application/zip")
                .body(TWO_NOTES_ZIP.to_vec()),
        );
        assert_eq!(res.status, Status::Unauthorized);
    }
